import numpy as np

# Assuming self.posns is a dictionary where keys are tokens and values are dictionaries with document keys and positions
if token not in self.posns:
    return []

if key is not None:
    # If a specific document key is provided, return the positions for that document only
    if key in self.posns[token]:
        return [np.array(self.posns[token][key])]
    else:
        return []
else:
